use crate::ciphers::speck::cipher::speck_encrypt;
use crate::ciphers::speck::keys::speck_default_key;
use crate::core::sample::sample_bytes;
use crate::core::timer::Stopwatch;

/// Time one encryption pass over `input_len` generated bytes.
pub fn speck_measure(input_len: usize) -> u128 {
    let data = sample_bytes(input_len);
    let key = speck_default_key();
    let watch = Stopwatch::start();
    let sealed = speck_encrypt(&data, key);
    std::hint::black_box(sealed.len());
    watch.elapsed_ns()
}
